struct RealtimeSampleMapStreamContext
{
    std::shared_ptr<AudioStreamConsumer> consumer;
    bool playbackStarted = false;
};

[[nodiscard]] bool restartRealtimeSampleMapStream(
    void* opaque,
    double sourceFrame,
    double signedSourceFrameIncrement) noexcept
{
    auto* context = static_cast<RealtimeSampleMapStreamContext*>(opaque);
    if (context == nullptr || context->consumer == nullptr)
        return false;
    if (!context->playbackStarted)
    {
        context->playbackStarted = true;
        return std::abs(
                   context->consumer->sourceFrameCursor()
                   - sourceFrame)
            <= 1.0e-12;
    }
    return context->consumer->restartPrepared(
        sourceFrame,
        signedSourceFrameIncrement);
}

[[nodiscard]] SampleMapPlaybackSource::ReadResult
readRealtimeSampleMapStream(
    void* opaque,
    double sourceFrame,
    double interpolationRightSourceFrame,
    double nextSourceFrame,
    double signedSourceFrameIncrement) noexcept
{
    auto* context = static_cast<RealtimeSampleMapStreamContext*>(opaque);
    if (context == nullptr || context->consumer == nullptr)
        return {};
    const auto streamed = context->consumer->readInterpolated(
        sourceFrame,
        interpolationRightSourceFrame,
        nextSourceFrame,
        signedSourceFrameIncrement);
    return {
        streamed.sample,
        streamed.status == AudioStreamReadStatus::Available,
    };
}

[[nodiscard]] bool relocateRealtimeSampleMapStream(
    void* opaque,
    double sourceFrame,
    double signedSourceFrameIncrement) noexcept
{
    auto* context = static_cast<RealtimeSampleMapStreamContext*>(opaque);
    return context != nullptr
        && context->consumer != nullptr
        && context->consumer->relocatePrepared(
            sourceFrame,
            signedSourceFrameIncrement);
}

