        {
            const auto slot = index - 1;
            const auto writeIndex =
                operation.memoryWriterRollbackJournalIndices[slot];
            if (writeIndex < operation.memoryWriterSamples.size())
                operation.memoryWriterSamples[writeIndex] =
                    operation.memoryWriterRollbackJournalValues[slot];
        }
        operation.memoryWriterCapturedFrames =
            state.memoryWriterCapturedFrames;
