// Copyable state owned by this session. This is also the declaration source
// for the offline journal; scratch is included to avoid hidden continuation
// dependencies. Atomic publications and noncopyable participants stay separate.
struct RealtimePairedControlCheckpointStorage
{
    std::vector<double> pairedStereoEventValueRollback;
    std::vector<talas::expr::ExpressionValue>
        pairedStereoVariableRollback;
    std::vector<talas::expr::ExpressionValue>
        pairedStereoVariableCandidateRollback;
    std::vector<std::uint16_t>
        pairedStereoSoundVariableRollback;
    std::vector<std::uint16_t>
        pairedStereoSoundVariableCandidateRollback;
    std::vector<talas::expr::ExpressionState>
        pairedStereoLiveExpressionStateRollback;
    std::vector<talas::expr::ExpressionState>
        pairedStereoLiveExpressionStateCandidateRollback;
    std::vector<double> pairedStereoLiveValueRollback;
    std::vector<double> pairedStereoLiveBlockRollback;
    std::vector<double> pairedStereoLiveCandidateRollback;
    std::vector<PreparedTimelineRamp>
        pairedStereoPreparedTimelineRampRollback;
    std::vector<SnapshotDirectRamp>
        pairedStereoSnapshotDirectRampRollback;
    std::vector<SnapshotDirectRamp>
        pairedStereoSnapshotDirectRampCandidateRollback;
    std::vector<RealtimeMidiVoiceRegion>
        pairedStereoMidiVoiceRegionRollback;
    std::vector<RealtimeMidiVoiceState>
        pairedStereoMidiVoiceStateRollback;
    std::vector<std::uint8_t>
        pairedStereoTypedGateTargetRollback;
};
static_assert(std::is_nothrow_swappable_v<RealtimePairedControlCheckpointStorage>);

// A copyable frame counter that the rendering thread writes while a
// control thread may read it, both relaxed. Copies take a snapshot.
struct RelaxedAtomicFrame
{
    RelaxedAtomicFrame() noexcept = default;
    RelaxedAtomicFrame(std::uint64_t frame) noexcept : value(frame) {}
    RelaxedAtomicFrame(const RelaxedAtomicFrame& other) noexcept
        : value(other.load())
    {
    }
    RelaxedAtomicFrame& operator=(const RelaxedAtomicFrame& other) noexcept
    {
        value.store(other.load(), std::memory_order_relaxed);
        return *this;
    }
    RelaxedAtomicFrame& operator=(std::uint64_t frame) noexcept
    {
        value.store(frame, std::memory_order_relaxed);
        return *this;
    }
    operator std::uint64_t() const noexcept { return load(); }
    [[nodiscard]] std::uint64_t load() const noexcept
    {
        return value.load(std::memory_order_relaxed);
    }

private:
    std::atomic<std::uint64_t> value = 0;
};

