                    inputIndices{
                        operation.audioInputBufferIndex,
                        operation.secondAudioInputBufferIndex,
                        operation.saturatorExtraInputBufferIndices[0],
                        operation.saturatorExtraInputBufferIndices[1]};
                const std::array<std::size_t, 4> outputIndices{
                    operation.outputBufferIndex,
                    *operation.secondaryOutputBufferIndex,
                    *operation.saturatorExtraOutputBufferIndices[0],
                    *operation.saturatorExtraOutputBufferIndices[1]};
