                std::ranges::copy(
                    operation.frequencyTrackerHistory,
                    operation.frequencyTrackerCandidateHistory.begin());
                auto candidateWriteIndex =
                    operation.frequencyTrackerHistoryWriteIndex;
                auto candidateCount = operation.frequencyTrackerHistoryCount;
                auto candidateHasPreviousInput =
                    operation.frequencyTrackerHasPreviousInput;
