            operation.harmonicResonatorJournalCount = 0;
            operation.harmonicResonatorRollbackWriteIndex =
                operation.harmonicResonatorWriteIndex;
            operation.harmonicResonatorRollbackBrightnessLowPass =
                operation.harmonicResonatorBrightnessLowPass;
            operation.harmonicResonatorRollbackAllpassOutput =
                operation.harmonicResonatorAllpassOutput;
            break;
