            std::ranges::fill(
                operation.dynamicRangeControllerDelayLine,
                0.0);
            std::ranges::fill(
                operation.dynamicRangeControllerDelayEpochs,
                0);
            operation.dynamicRangeControllerLogicalCapacity =
                operation.dynamicRangeControllerInitialLogicalCapacity;
            operation.dynamicRangeControllerWriteIndex = 0;
            operation.dynamicRangeControllerJournalCount = 0;
            operation.dynamicRangeControllerRollbackWriteIndex = 0;
            operation.dynamicRangeControllerEnvelope = 0.0;
            operation.dynamicRangeControllerRollbackEnvelope = 0.0;
