            if (operation.spectrumFilterBank != nullptr)
                operation.spectrumFilterBank->reset();
            break;
        case RealtimeOperationKind::GrainCloud:
            if (operation.grainCloudScheduler != nullptr)
                operation.grainCloudScheduler->reset();
            operation.grainCloudRenderedFrames = 0;
            operation.grainCloudRetainedGrainLimit =
                operation.grainCloudInitialRetainedGrainLimit;
            operation.grainCloudLatches = {};
