        case RealtimeOperationKind::SampleCloud:
            if (operation.sampleCloudScheduler != nullptr)
                operation.sampleCloudScheduler->reset();
            operation.sampleCloudRenderedFrames = 0;
            operation.sampleCloudRetainedGrainLimit =
                operation.sampleCloudInitialRetainedGrainLimit;
