        case RealtimeOperationKind::VocoderChannelBank:
            if (operation.linearVocoderBank != nullptr)
                operation.linearVocoderBank->reset();
            break;
        case RealtimeOperationKind::DelayWithFeedback:
            // ADR-0025: Prezero empties the line when the transport
            // restarts; without it the line keeps what it holds.
            if (operation.delayPrezero)
            {
                std::ranges::fill(operation.delayLine, 0.0);
                operation.delayWriteIndex = 0;
            }
            operation.sharedDelayStarted = false;
            operation.delayGlide.started = false;
            break;
        case RealtimeOperationKind::ReverbSection:
            // ADR-0025: Prezero empties the line when the transport
            // restarts; without it the line keeps what it holds.
            if (operation.delayPrezero)
            {
                std::ranges::fill(operation.reverbDelayLine, 0.0);
                operation.reverbWriteIndex = 0;
            }
            operation.sharedDelayStarted = false;
            operation.delayGlide.started = false;
            break;
        case RealtimeOperationKind::NativeForwardStft:
            if (operation.nativeForwardStft != nullptr)
                operation.nativeForwardStft->reset();
