        case RealtimeOperationKind::NativeInverseStft:
            if (operation.nativeInverseStft != nullptr)
                operation.nativeInverseStft->reset();
            break;
        case RealtimeOperationKind::LiveSpectralAnalysis:
            if (operation.liveSpectralAnalysis != nullptr)
                operation.liveSpectralAnalysis->reset();
            break;
        case RealtimeOperationKind::PartialSpectrumLegacyHold:
            operation.partialSpectrumLegacyHoldCount = 0;
