                    const auto scalar = talas::expr::ValueDomain::Scalar;
                    const auto hertz = talas::expr::ValueDomain::Hertz;
                    std::optional<RealtimeScalar> first;
                    std::optional<RealtimeScalar> second;
                    std::optional<RealtimeScalar> third;
                    std::optional<RealtimeScalar> fourth;
                    std::optional<RealtimeScalar> fifth;
                    std::optional<RealtimeScalar> sixth;
