                        const auto cycles = live("cycles", validateCdpDistortEnvelopeCyclesRealtimeScalar);
                        const auto trough = live("trough", validateUnitIntervalRealtimeScalar);
                        const auto exponent = live("exponent", validateCdpDistortExponentRealtimeScalar);
                        const auto* envelope = findParameter(step, "envelope");
                        using Shape = talas::cdp::DistortEnvelope::Shape;
