                    const auto* pitches = findParameter(step, "pitches");
                    const auto* bands = findParameter(step, "bands");
                    const auto* partials = findParameter(step, "partials");
                    const auto* q = findParameter(step, "q");
                    const auto* gain = findParameter(step, "gain");
                    const auto* doubleFiltering = findParameter(step, "doubleFiltering");
