                    std::size_t stepOutputCount = 0;
                    std::size_t gateOutputCount = 0;
                    for (const auto& buffer : plan.buffers)
                    {
                        if (buffer.nodeId != step.nodeId
                            || buffer.scopeId != step.scopeId
                            || !prepared_output_bindings::isOriginalBuffer(plan, buffer))
                        {
                            continue;
                        }
                        ++ownedOutputCount;
                        stepOutputCount += static_cast<std::size_t>(
                            buffer.portId == "step"
                            && buffer.type == talas::core::PortType::Control);
                        gateOutputCount += static_cast<std::size_t>(
                            buffer.portId == "gate"
                            && buffer.type == talas::core::PortType::Control);
                    }
                    const auto stepOutput = findOutputBuffer(
                        plan, step, "step", talas::core::PortType::Control);
                    const auto gateOutput = findOutputBuffer(
                        plan, step, "gate", talas::core::PortType::Control);
                    const auto clockInput = findInputBuffer(
                        plan, step, "clock", talas::core::PortType::Control);
                    const auto* division = findParameter(step, "division");
                    const auto* steps = findParameter(step, "steps");
                    const auto* reset = findParameter(step, "reset");
                    const auto hasExactSupportedAuthority =
                        graph.compiledClockDividerRegistryAuthority_
                        && hasExactDynamicUtilityAuthority(
                            KernelKind::ClockDivider,
                            true,
                            talas::core::ExecutionSupport::Supported,
                            talas::core::ExecutionSupport::Supported,
                            true);
                    const auto hasSubsetCompatibilityAuthority =
                        hasExactDynamicUtilityAuthority(
                            KernelKind::ClockDivider,
                            true,
                            talas::core::ExecutionSupport::Subset,
                            talas::core::ExecutionSupport::Subset,
                            true);
