                    const auto hasStaticResetFallback =
                        reset != nullptr
                        && reset->expression.has_value()
                        && reset->expression->identifiers().empty()
                        && !reset->choice.has_value()
                        && !reset->boolean.has_value()
                        && !reset->resource.has_value()
                        && !reset->text.has_value()
                        && std::isfinite(reset->value);
                    if (!(hasExactSupportedAuthority
                            || hasSubsetCompatibilityAuthority)
                        || !hasExactInputs
                        || ownedOutputCount != 2
                        || stepOutputCount != 1
                        || gateOutputCount != 1
                        || step.parameters.size() != 3
                        || step.parameters[0].id != "division"
                        || step.parameters[1].id != "steps"
                        || step.parameters[2].id != "reset"
                        || !stepOutput.has_value() || !gateOutput.has_value()
                        || !clockInput.has_value()
                        || division == nullptr || steps == nullptr
                        || !hasExactPreparedParameterAuthority(
                            *division, talas::expr::ValueDomain::Scalar, true)
                        || !hasExactPreparedParameterAuthority(
                            *steps, talas::expr::ValueDomain::Scalar, true)
                        || !hasExactPreparedParameterAuthority(
                            *reset, talas::expr::ValueDomain::Scalar, true)
                        || !hasStaticResetFallback)
                    {
                        fail("Realtime Clock Divider requires bounded Scalar integer parameters and a clock input");
                        return;
                    }
