                    const auto liveStepSize = prepareRealtimeScalar(
                        *stepSize,
                        validatePositiveRealtimeScalar,
                        "Quantizer stepSize");
                    const auto liveOffset = prepareRealtimeScalar(
                        *offset,
                        validateFiniteRealtimeScalar,
                        "Quantizer offset");
                    if (!liveStepSize.has_value() || !liveOffset.has_value())
                        return;
