                    const auto right = findOutputBuffer(
                        plan, step, "rightOut", talas::core::PortType::Audio);
                    const auto first = findInputBuffer(
                        plan, step, "snd1", talas::core::PortType::Audio);
                    const auto second = findInputBuffer(
                        plan, step, "snd2", talas::core::PortType::Audio);
                    const auto* pan = findParameter(step, "pan");
                    const auto* scale = findParameter(step, "scale");
                    const auto* fade = findParameter(step, "fade");
                    const auto* type = findParameter(step, "type");
                    const auto hasPanInput = findInput(step, "pan") != nullptr;
