                    const auto bindingIndex = inputBinding == nullptr
                        ? step.inputs.size()
                        : static_cast<std::size_t>(
                            inputBinding - step.inputs.data());
                    const auto sourceStep = inputBinding == nullptr
                        ? plan.steps.end()
                        : std::ranges::find_if(
                            plan.steps,
                            [&](const CompileStep& candidate) {
                                return candidate.nodeId
                                        == inputBinding->sourceNodeId
                                    && candidate.scopeId
                                        == inputBinding->sourceScopeId;
                            });
