                    const auto tracker = findInputBuffer(plan, step, "freqTracker", talas::core::PortType::Control);
                    const auto* frequencyScale = findParameter(step, "frequencyScale");
                    const auto* maxScale = findParameter(step, "maxScale");
                    const auto* window = findParameter(step, "window");
                    const auto* delay = findParameter(step, "delay");
                    const bool hasFrequencyScaleInput = findInput(step, "frequencyScale") != nullptr;
                    const bool hasDelayInput = findInput(step, "delay") != nullptr;
                    const bool hasMaxScaleInput = findInput(step, "maxScale") != nullptr;
