                    const auto input = findInputBuffer(plan, step, "audioIn", talas::core::PortType::Audio);
                    const auto* type = findParameter(step, "type");
                    const auto* scale = findParameter(step, "scale");
                    const auto* decayTime = findParameter(step, "decayTime");
                    const auto* delay = findParameter(step, "delay");
                    const auto* delayScale = findParameter(step, "delayScale");
