                        operation.midiVoiceRootBufferIndices.push_back(
                            voice.audioOutputBufferIndex);
                        if (hasRightRoot)
                            operation.midiVoiceRightRootBufferIndices.push_back(
                                *voice.rightAudioOutputBufferIndex);
