                    const bool hasMaxFrequencyInput = findInput(step, "maxFrequency") != nullptr;
                    const bool hasConfidenceInput = findInput(step, "confidence") != nullptr;
                    const bool hasScaleInput = findInput(step, "scale") != nullptr;
