                    { fail("Realtime renderer requires valid Iterated Waveshaper iterations, scale, and wavetable"); return; }
                    const auto table = std::ranges::find_if(settings.tableResources, [&](const TableResource& candidate) {
                        return candidate.id == *wavetable->resource;
                    });
                    if (table == settings.tableResources.end() || table->samples.empty())
                    { fail("Realtime renderer requires a non-empty Iterated Waveshaper wavetable resource"); return; }
                    for (const auto sample : table->samples)
                        if (!std::isfinite(sample))
                        { fail("Realtime renderer requires finite Iterated Waveshaper wavetable samples"); return; }
                    operationStorage->emplace(RealtimeOperationKind::IteratedWaveshaper, *output, *input);
                    auto& operation = **operationStorage;
                    operation.iteratedWaveshaperSamples = table->samples;
