                    const auto output = findOutputBuffer(plan, step, "audioOut", talas::core::PortType::Audio);
                    const auto input = findInputBuffer(plan, step, "audioIn", talas::core::PortType::Audio);
                    const auto* inValues = findParameter(step, "inValues");
