namespace talas::runtime
{
RealtimeRenderSession::RealtimeRenderSession(const PreparedRuntimeGraph& graph, bool parentOwned)
    : impl_(std::make_unique<Impl>(graph, parentOwned)) {}
PreparedSourceCallback::PreparedSourceCallback(const PreparedRuntimeGraph& graph)
    : session_(new RealtimeRenderSession(graph, true)), defaultMidiChannel_(graph.renderSettings().defaultMidiChannel)
{
    if (!session_->ready()) return;
    readsKeyDown_ = session_->hasEventValueBinding("KeyDown", talas::expr::ValueDomain::Scalar);
    readsPitch_ = session_->hasEventValueBinding("Pitch", talas::expr::ValueDomain::NoteNumber);
    readsKeyVelocity_ = session_->hasEventValueBinding("KeyVelocity", talas::expr::ValueDomain::Scalar);
    readsKeys_ = readsKeyDown_ || readsPitch_ || readsKeyVelocity_;
}
PreparedSourceCallback::~PreparedSourceCallback() { rollback(); }
struct PreparedSourceCallback::PreparedPoint::State
{
    std::shared_ptr<const std::uint8_t> owner;
    std::unique_ptr<RealtimeRenderSession::Impl::SourceResetPoint> point;
};
PreparedSourceCallback::PreparedPoint::PreparedPoint(std::unique_ptr<State> state) : state_(std::move(state)) {}
PreparedSourceCallback::PreparedPoint::~PreparedPoint() = default;
std::unique_ptr<PreparedSourceCallback::PreparedPoint> PreparedSourceCallback::capturePreparedPoint()
{
    if (pending_ || !ready()) return {};
    auto captured = session_->impl_->captureSourceResetPoint();
    if (!captured) return {};
    auto state = std::make_unique<PreparedPoint::State>();
    state->owner = pointOwner_;
    state->point = std::move(captured);
    return std::unique_ptr<PreparedPoint>(new PreparedPoint(std::move(state)));
}
bool PreparedSourceCallback::canRestorePreparedPoint(const PreparedPoint& point) const noexcept
{
    return !pending_ && ready() && point.state_ && point.state_->owner == pointOwner_
        && point.state_->point && session_->impl_->canRestoreSourceResetPoint(*point.state_->point);
}
bool PreparedSourceCallback::restorePreparedPoint(PreparedPoint& point) noexcept
{
    if (!canRestorePreparedPoint(point)) return false;
    key_ = pendingKey_ = -1;
    return session_->impl_->restoreSourceResetPoint(*point.state_->point);
}
bool PreparedSourceCallback::canResetToPreparedPoint() const noexcept
{
    return !pending_ && ready() && session_->impl_->sourceResetPoint
        && session_->impl_->canRestoreSourceResetPoint(*session_->impl_->sourceResetPoint);
}
std::unique_ptr<RealtimeRenderSession::OfflineTransaction> PreparedSourceCallback::beginOfflineTransaction()
{ return pending_ ? nullptr : session_->beginOfflineTransaction(); }
bool PreparedSourceCallback::ready() const noexcept { return session_->ready(); }
std::string_view PreparedSourceCallback::error() const noexcept { return session_->error(); }
bool PreparedSourceCallback::pending() const noexcept { return pending_; }
bool PreparedSourceCallback::renderTentative(RealtimeAudioInputBlock input,
    double* const* outputs, std::size_t channels, std::size_t frames, bool compositionAdvancing) noexcept
{
    if (timelineDecisionPending_ || pending_ || frames == 0 || !session_->impl_->beginSourceStreams()) return false;
    session_->impl_->sourceCompositionAdvancing = compositionAdvancing;
    pending_ = session_->render(input, outputs, channels, frames);
    session_->impl_->sourceCompositionAdvancing = true;
    if (!pending_) session_->impl_->finishSourceStreams(false);
    return pending_;
}
bool PreparedSourceCallback::renderNextSegment(RealtimeAudioInputBlock input,
    double* const* outputs, std::size_t channels, std::size_t frames, bool compositionAdvancing) noexcept
{
    if (!pending_ || timelineDecisionPending_) return false;
    if (session_->impl_->renderNextSourceSegment(input, outputs, channels, frames, compositionAdvancing)) return true;
    rollback();
    return false;
}
bool PreparedSourceCallback::bindTimelineWaitSteps(std::span<const std::size_t> steps)
{
    if (pending_ || !ready()) return false;
    for (const auto step : steps)
        if (!session_->impl_->waitActivation || !session_->impl_->waitActivation->gateOperation(step)) return false;
    timelineWaitSteps_.assign(steps.begin(), steps.end());
    return true;
}
bool PreparedSourceCallback::renderTimelineFrame(RealtimeAudioInputBlock input, double* const* outputs,
    std::size_t channels) noexcept
{
    if (timelineDecisionPending_) return false;
    const auto rendered = pending_ ? renderNextSegment(input, outputs, channels, 1, false)
        : renderTentative(input, outputs, channels, 1, false);
    timelineDecisionPending_ = rendered;
    return rendered;
}
bool PreparedSourceCallback::timelineHeld() const noexcept
{
    if (!timelineDecisionPending_) return false;
    return session_->impl_->timelineWaitHeld(timelineWaitSteps_);
}
bool PreparedSourceCallback::resolveTimelineFrame(bool advanceComposition) noexcept
{
    if (!pending_ || !timelineDecisionPending_) return false;
    if (advanceComposition)
    {
        if (session_->impl_->sourceCompositionFrame == std::numeric_limits<std::uint64_t>::max()) return false;
        ++session_->impl_->sourceCompositionFrame;
    }
    timelineDecisionPending_ = false;
    return true;
}
bool PreparedSourceCallback::prepareResetPoint()
{ return !pending_ && session_->impl_->prepareSourceResetPoint(); }
bool PreparedSourceCallback::resetToPreparedPoint() noexcept
{ rollback(); key_ = pendingKey_ = -1; return session_->impl_->restoreSourceResetPoint(); }
bool PreparedSourceCallback::prepareStreamWindows(AudioStreamPreparedWindowBudget& budget)
{ return !pending_ && ready() && session_->impl_->prepareSourceStreamWindows(budget); }
std::span<const RealtimeMidiOutputEvent> PreparedSourceCallback::midiOutputEvents() const noexcept
{
    if (!ready() || !session_->impl_->hasMidiOutputTap
        || session_->impl_->terminalEventCandidateCount > session_->impl_->terminalEventCandidates.size())
        return {};
    return {session_->impl_->terminalEventCandidates.data(), session_->impl_->terminalEventCandidateCount};
}
std::uint16_t PreparedSourceCallback::midiChannels() const noexcept
{
    if (!ready()) return 0;
    auto channels = session_->impl_->liveMidiChannels();
    if (readsKeys_ && defaultMidiChannel_ >= 1 && defaultMidiChannel_ <= 16)
        channels |= static_cast<std::uint16_t>(1U << (defaultMidiChannel_ - 1U));
    return channels;
}
bool PreparedSourceCallback::scheduleMidiNote(RealtimeMidiNoteEvent event, std::size_t frameOffset) noexcept
{
    if (pending_ || timelineDecisionPending_ || !ready()) return false;
    const auto result = session_->impl_->scheduleMidiNote(event, frameOffset);
    if (result == RealtimeMidiDispatchResult::Handled) return true;
    if (result != RealtimeMidiDispatchResult::NotHandled || !readsKeys_ || event.channel != defaultMidiChannel_)
        return false;
    // The keyboard's values, as the bridge plays them for a Sound alone: a
    // key up releases only the last key down.
    std::array<RealtimeEventValueUpdate, 3> updates{};
    std::size_t count = 0;
    const auto add = [&](bool reads, std::string_view name, double value, talas::expr::ValueDomain domain) {
        if (reads) updates[count++] = {name, value, domain};
    };
    if (event.kind == RealtimeMidiNoteKind::NoteOff)
    {
        if (event.note != pendingKey_) return false;
        add(readsKeyDown_, "KeyDown", 0.0, talas::expr::ValueDomain::Scalar);
    }
    else
    {
        add(readsPitch_, "Pitch", static_cast<double>(event.note), talas::expr::ValueDomain::NoteNumber);
        add(readsKeyVelocity_, "KeyVelocity", static_cast<double>(event.velocity) / 127.0, talas::expr::ValueDomain::Scalar);
        add(readsKeyDown_, "KeyDown", 1.0, talas::expr::ValueDomain::Scalar);
    }
    if (count != 0 && !session_->scheduleEventValues(std::span<const RealtimeEventValueUpdate>(updates.data(), count), frameOffset))
        return false;
    pendingKey_ = event.kind == RealtimeMidiNoteKind::NoteOff ? -1 : event.note;
    return true;
}
std::vector<RealtimeEventValueUpdate> PreparedSourceCallback::globalEventValues() const
{
    if (!ready())
        return {};
    std::vector<RealtimeEventValueUpdate> values(session_->impl_->eventValues.size());
    const auto count = session_->captureCurrentGlobalEventValues(values);
    values.resize(count.value_or(0));
    return values;
}
bool PreparedSourceCallback::scheduleEventValue(
    std::string_view name, double value, talas::expr::ValueDomain domain, std::size_t frameOffset) noexcept
{
    if (pending_ || timelineDecisionPending_ || !ready()) return false;
    return session_->scheduleEventValue(name, value, domain, frameOffset);
}
void PreparedSourceCallback::commit() noexcept
{
    if (timelineDecisionPending_) { rollback(); return; }
    if (pending_)
    {
        session_->impl_->commitDeferredCallback();
        session_->impl_->finishSourceStreams(true);
    }
    pending_ = false;
    key_ = pendingKey_;
    session_->impl_->discardSourceMidi();
}
void PreparedSourceCallback::rollback() noexcept
{
    timelineDecisionPending_ = false;
    if (pending_)
    {
        session_->impl_->rollbackDeferredCallback();
        session_->impl_->finishSourceStreams(false);
    }
    pending_ = false;
    // A retried callback forwards its notes again.
    pendingKey_ = key_;
    session_->impl_->discardSourceMidi();
}
}
